// ─── File: ProxyTxDemo.java ───
// Runnable demo simulating a CGLIB proxy that reads @Transactional from the
// IMPLEMENTATION class. Shows why putting it only on the interface would fail.

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class ProxyTxDemo {
    private static final Logger log = Logger.getLogger("BankProxy");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountRepository repo = new AccountRepository();
        TransferServiceImpl impl = new TransferServiceImpl(repo, log);
        // CGLIB-style proxy: reads @Transactional from the IMPLEMENTATION
        TransferService proxied = new CglibStyleTxProxy(impl, log);

        log.info(() -> "=== Successful transfer via CGLIB proxy ===");
        proxied.transfer("SAV2001", "CUR3001", new BigDecimal("50000"));

        log.info(() -> "=== Failing transfer (rolls back) ===");
        try {
            proxied.transfer("SAV2001", "CUR3001", new BigDecimal("9999999"));
        } catch (RuntimeException ex) {
            log.warning(() -> "Caller saw failure: " + ex.getMessage());
        }

        log.info(() -> "FINAL Rajesh = " + repo.findById("SAV2001").getBalance()
                      + ", Priya = " + repo.findById("CUR3001").getBalance());
    }
}

// ─── model/Account.java ───
class Account {
    private final String accountId; private final String holderName; private BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId=id; holderName=name; balance=bal; }
    String getAccountId() { return accountId; }
    BigDecimal getBalance() { return balance; }
    void debit(BigDecimal a) { balance = balance.subtract(a); }
    void credit(BigDecimal a) { balance = balance.add(a); }
}

// ─── repository/AccountRepository.java ───
class AccountRepository {
    private final Map<String, Account> store = new HashMap<>();
    private final Map<String, BigDecimal> snapshot = new HashMap<>();
    AccountRepository() {
        store.put("SAV2001", new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000")));
        store.put("CUR3001", new Account("CUR3001", "Priya Sharma", new BigDecimal("250000")));
    }
    Account findById(String id) { return store.get(id); }
    // Simple snapshot/restore to simulate commit vs rollback
    void begin() { snapshot.clear(); store.forEach((k,v) -> snapshot.put(k, v.getBalance())); }
    void rollback() { store.forEach((k,v) -> v.credit(snapshot.get(k).subtract(v.getBalance()))); }
}

// ─── service/TransferService.java — INTERFACE, deliberately NO @Transactional ───
interface TransferService {
    void transfer(String from, String to, BigDecimal amount);
}

// ─── service/TransferServiceImpl.java — @Transactional lives HERE ───
// NOT final, methods NOT final → CGLIB can subclass and proxy it.
class TransferServiceImpl implements TransferService {
    private final AccountRepository repo; private final Logger log;
    TransferServiceImpl(AccountRepository repo, Logger log) { this.repo=repo; this.log=log; }

    // @Transactional  <-- on the implementation, honored by JDK AND CGLIB
    @Override
    public void transfer(String from, String to, BigDecimal amount) {
        Account f = repo.findById(from);
        Account t = repo.findById(to);
        if (f.getBalance().compareTo(amount) < 0)
            throw new RuntimeException("Insufficient balance in " + from);
        f.debit(amount);
        t.credit(amount);
        log.info(() -> "transfer body applied " + from + "->" + to + " Rs." + amount);
    }
}

// ─── A CGLIB-style proxy: reads tx metadata from the IMPLEMENTATION class ───
// Real Spring generates this subclass at runtime. Here we simulate it.
class CglibStyleTxProxy implements TransferService {
    private final TransferServiceImpl target; private final Logger log;
    CglibStyleTxProxy(TransferServiceImpl target, Logger log) { this.target=target; this.log=log; }
    @Override
    public void transfer(String from, String to, BigDecimal amount) {
        // CGLIB inspects the concrete class method for @Transactional -> found
        AccountRepositoryHolder.repo.begin();
        log.fine(() -> "PROXY: @Transactional found on impl → BEGIN");
        try {
            target.transfer(from, to, amount);
            log.info(() -> "PROXY: COMMIT");
        } catch (RuntimeException ex) {
            AccountRepositoryHolder.repo.rollback();
            log.severe(() -> "PROXY: ROLLBACK (" + ex.getMessage() + ")");
            throw ex;
        }
    }
}

// Small holder so the demo proxy can reach the repository for begin/rollback.
class AccountRepositoryHolder { static AccountRepository repo; }

// ─── Clean log formatter ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel().getName(), r.getMessage());
    }
}
