// ─── File: src/main/java/com/bank/proxy/service/TransferServiceImpl.java ───
package com.bank.proxy.service;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Service
public class TransferServiceImpl implements TransferService {
    private final AccountRepository repo;
    public TransferServiceImpl(AccountRepository repo) { this.repo = repo; }

    // @Transactional on the IMPLEMENTATION — works under CGLIB (Boot default) and JDK.
    // Class and method are NOT final so CGLIB can subclass/override.
    @Override
    @Transactional
    public void transfer(String from, String to, BigDecimal amount) {
        var f = repo.findById(from).orElseThrow();
        var t = repo.findById(to).orElseThrow();
        if (f.getBalance().compareTo(amount) < 0)
            throw new IllegalStateException("Insufficient balance");
        f.debit(amount); t.credit(amount);
        repo.save(f); repo.save(t);
    }
}
